检查信息：{"全血细胞计数（CBC）": {"result": {"血白细胞计数": "WBC：68.4 x 10^9/L [参考范围：4.5-11.0 x 10^9/L]", "血红蛋白": "Hgb：98 g/L [参考范围：120-160 g/L]", "血小板计数": "PLT：92 x 10^9/L [参考范围：150-400 x 10^9/L]"}, "status": "abnormal", "abnormal_indicators": ["血白细胞计数", "血红蛋白", "血小板计数"]}, "外周血涂片": {"result": {"外周血涂片其他异常所见": "可见大量成熟小淋巴细胞，未见寄生虫或包涵体。", "异型细胞或原始细胞": "未见明显异型细胞或原始细胞。", "白细胞分类计数": "中性粒细胞 15%、淋巴细胞 82%、单核细胞 3%、嗜酸性粒细胞 0%、嗜碱性粒细胞 0%。［参考值：中性粒细胞 40-70%、淋巴细胞 20-40%、单核细胞 2-8%、嗜酸性粒细胞 1-4%、嗜碱性粒细胞 0-1%。］", "白细胞形态": "大部分为成熟小淋巴细胞，胞浆少，染色质致密，部分细胞可见‘涂抹细胞’（smudge cells）。", "红细胞形态": "正细胞性、正色素性，中央淡染区约占细胞直径的三分之一；可见少量缗钱状排列，无明显大小不等或形态异常。", "血小板形态与分布": "血小板体积偏大，形态大致正常，分布欠均匀。", "血小板数量": "数量减少（估计约 92,000/μL）。［参考值：数量充足（估计 150,000-400,000/μL）。］", "血小板聚集": "可见散在血小板聚集现象。"}, "status": "abnormal", "abnormal_indicators": ["外周血涂片其他异常所见", "白细胞分类计数", "白细胞形态", "血小板形态与分布", "血小板数量", "血小板聚集"]}, "凝血功能全套": {"result": {"D-二聚体": "0.32 mg/L FEU［参考值：<0.5 mg/L FEU（或 <250 ng/mL DDU）］", "凝血酶原时间": "12.4 秒［参考值：11-13.5 秒］", "凝血酶时间": "16.5 秒［参考值：14-19 秒］", "国际标准化比值": "1.05［参考值：0.8-1.2］", "活化部分凝血活酶时间": "29.8 秒［参考值：25-35 秒］", "血浆纤维蛋白原": "3.1 g/L［参考值：2.0-4.0 g/L］"}, "status": "normal", "abnormal_indicators": []}}
