检查信息：{"全血细胞计数（CBC）": {"result": {"血小板计数": "PLT：12 x 10^9/L［参考范围：150-400 x 10^9/L］", "血红蛋白": "Hgb：108 g/L［参考范围：120-160 g/L］", "血白细胞计数": "WBC在参考范围内。"}, "status": "abnormal", "abnormal_indicators": ["血小板计数", "血红蛋白", "血白细胞计数"]}, "外周血涂片": {"result": {"血小板数量": "显著血小板减少［参考值：数量充足（估计 150,000-400,000/μL）。］", "血小板形态与分布": "可见偶见大型血小板", "异型细胞或原始细胞": "未见原始细胞", "红细胞形态": "其余无明显异常"}, "status": "abnormal", "abnormal_indicators": ["血小板数量", "血小板形态与分布", "异型细胞或原始细胞"]}}

